        raise FhirValidationError(
            "Bundle.type 仅限 %s" % "、".join(BUNDLE_TYPES)
        )

    if "entry" in bundle and not isinstance(bundle["entry"], list):
        raise FhirValidationError("Bundle.entry 必须为数组")


def _entry_failure(pos, resource_type, stage, code, expression, diagnostics):
    issue = {
        "severity": "error",
        "code": code,
        "entryIndex": pos,
        "expression": [expression],
        "diagnostics": diagnostics,
    }
    return {
        "index": pos,
        "resource_type": resource_type,
        "stage": stage,
        "status": 400,
        "issues": [issue],
        "mappings": [],
    }


def evaluate_entry(entry, pos, term_index):
    """逐项执行 request 检查、既有资源校验与术语映射；结果以数据返回，不抛异常。"""
    label = "Bundle.entry[%d]" % pos
    resource_type = None
    if isinstance(entry, dict) and isinstance(entry.get("resource"), dict):
        candidate = entry["resource"].get("resourceType")
        if _is_nonempty_str(candidate):
            resource_type = candidate

    def fail(stage, code, expression, diagnostics):
        return _entry_failure(
            pos, resource_type, stage, code, expression, diagnostics
        )

    if not isinstance(entry, dict):
        return fail("request", "invalid", label, "%s 必须为对象" % label)

    request = entry.get("request")
    if not isinstance(request, dict):
        return fail(
            "request", "invalid", label + ".request",
            "%s.request 必须为对象" % label,
        )
    if "resource" not in entry:
        return fail(
            "request", "invalid", label + ".resource",
            "%s 缺少 resource" % label,
        )
    resource = entry["resource"]

    method = request.get("method")
    if not _is_nonempty_str(method):
        return fail(
            "request", "invalid", label + ".request.method",
            "%s.request.method 必须为非空字符串" % label,
        )
    if method not in ENTRY_METHODS:
        return fail(
            "request", "not-supported", label + ".request.method",
            "%s.request.method 仅支持 %s" % (label, "、".join(ENTRY_METHODS)),
        )

    url = request.get("url")
    if not _is_nonempty_str(url):
        return fail(
            "request", "invalid", label + ".request.url",
            "%s.request.url 必须为非空字符串" % label,
        )
    actual_type = resource.get("resourceType") if isinstance(resource, dict) else None
    if url.split("/")[0] != actual_type:
        return fail(
            "request", "invalid", label + ".request.url",
            "%s.request.url 首段必须与 resource.resourceType 一致" % label,
        )

    try:
        validate_resource(resource)
    except FhirValidationError as exc:
        return fail("validation", "processing", label + ".resource", str(exc))

    try:
        mappings = apply_mappings(resource, term_index)
    except GatewayError as exc:
        return fail("mapping", "processing", label + ".resource", str(exc))

    return {
        "index": pos,
        "resource_type": resource_type,
        "stage": "completed",
        "status": 200,
        "issues": [],
        "mappings": mappings,
    }


def process_execution_bundle(bundle, term_maps, audit_context, audit_path):
    """transaction/batch 批量执行：逐项校验与映射，不落业务库，每次提交一条审计。"""
    validate_execution_bundle(bundle)
    term_index = build_term_index(term_maps)

    entries = bundle.get("entry") or []
    results = [
        evaluate_entry(entry, pos, term_index)
        for pos, entry in enumerate(entries)
    ]
    failed = [r for r in results if r["status"] != 200]

    # transaction 全有或全无：任一失败整体 400；batch 各项独立，整体恒 200。
    if bundle["type"] == "transaction" and failed:
        overall_status = 400
    else:
        overall_status = 200

    response_entries = []
    for r in results:
        item = {
            "index": r["index"],
            "resourceType": r["resource_type"],
            "status": r["status"],
        }
        if r["issues"]:
            item["outcome"] = {
                "resourceType": "OperationOutcome",
                "issue": r["issues"],
            }
        response_entries.append(item)

    response_bundle = {
        "resourceType": "Bundle",
        "type": bundle["type"] + "-response",
        "entry": response_entries,
    }

    mappings = []
    for r in results:
        mappings.extend(r["mappings"])

    # 审计只留结构元数据：索引、资源类型、阶段、状态与问题代码；
    # 不写资源正文、患者姓名/标识，也不写术语映射原文。
    audit = {
        "request_id": audit_context["request_id"],
        "actor": audit_context["actor"],
        "recorded_at": audit_context["recorded_at"],
        "decision": "accepted" if overall_status == 200 else "rejected",
        "audit_id": uuid.uuid4().hex,
        "bundle_type": bundle["type"],
        "entry_total": len(results),
        "entry_succeeded": len(results) - len(failed),
        "entry_failed": len(failed),
        "status": overall_status,
        "entries": [
            {
                "index": r["index"],
                "resource_type": r["resource_type"],
                "stage": r["stage"],
                "status": r["status"],
                "issues": [issue["code"] for issue in r["issues"]],
            }
            for r in results
        ],
    }

    # 先落审计，再输出 stdout，保证审计失败时 stdout 一定为空。
    append_audit_line(audit_path, audit)

    result = {
        "status": overall_status,
        "resource_type": "Bundle",
        "resource": response_bundle,
        "mappings": mappings,
        "audit": audit,
    }
    return json.dumps(result, ensure_ascii=False)

